@import url('https://fonts.googleapis.com/css2?family=VT323&display=swap');

* {
    padding: 0;
    margin: 0;
    box-sizing: border-box;
}

:root {
    --grain:url("data:image/png;base64,");
}

body {
    background-color: black;
    display: flex;
    align-items: center;
    justify-content: center;
    height: 100vh;
    width: 100vw;
    overflow: hidden;
}

.terminal_ {
    display: flex;
    justify-content: center;
    align-items: center;
    
    background: linear-gradient(to right, rgb(180, 102, 0), rgb(180, 102, 0));
    color: rgba(134, 76, 0, 0.822);

    background-size: contain;
    font-family: 'VT323', monospace;
    position: relative;
    filter: blur(0.08vh);
    z-index: 0;
}


@media only screen and (max-width: calc(4/3 * 100vh)) {
    
    .terminal_ {
        width: 100vw;
        height: calc(3/4 * 100vw);
    }
}

@media only screen and (min-width: calc(4/3 * 100vh)) {
    
    .terminal_ {
        height: 100vh;
        width: calc(4/3 * 100vh);
    }
}

.vignette {
    position: absolute;
    width: 100%;
    height:100%;
    background-image: radial-gradient(circle, transparent, rgba(0, 0, 0, 0.952) 100%);
    z-index: 1;
}


.noise {
    position: absolute;
    width: 100%;
    height:100%;
    background: var(--grain);
    mix-blend-mode: multiply;
    background-size: 50%;
    opacity: 55%;
    z-index: 2;
}

.text-area_ {
    height: 90%;
    width: 90%;
    border: 3px solid rgba(134, 76, 0, 0.822);
    z-index: 3;
    position: relative;
}

.initialize {
    position: absolute;
    bottom: 0;
    padding: 0.5rem 1rem;
    font-size: 1.5rem;
    user-select: none;
}

.initialize div {
    display: inline;
    padding: 0;
    animation: example 3s steps(4, end);
    animation-iteration-count:infinite;
}

@keyframes example {
    0% {
        clip-path: inset(0 100% 0 0);
    }
    100% {
        clip-path: inset(0 0 0 0)
    }
}



.terminal, span, .cmd, div, .terminal-error {
    --color: rgba(216, 122, 0, 0.966);
    --error-color: rgba(175, 0, 38, 0.99);
    --background: transparent;
    font-family: 'VT323', monospace;
}
.terminal {
    --size: 1.2;
}
.terminal-image {
    max-width: 50vw;
    max-height: 60vh;
}
@media only screen and (max-width: 600px) {
    
    .terminal-image {
        max-width: 70vw;
    }
}

